INSERT OR IGNORE INTO "PopulationGroups" ("Id", "Code", "DisplayName", "MinAgeMonths", "MaxAgeMonths", "Sex", "LifeStage", "Notes") VALUES (19, 'child', '儿童', 48, 131, 'NotSpecified', '儿童期', NULL);
INSERT OR IGNORE INTO "PopulationGroups" ("Id", "Code", "DisplayName", "MinAgeMonths", "MaxAgeMonths", "Sex", "LifeStage", "Notes") VALUES (20, 'adult', '成人', 216, 599, 'NotSpecified', '成年期', NULL);
INSERT OR IGNORE INTO "PopulationGroups" ("Id", "Code", "DisplayName", "MinAgeMonths", "MaxAgeMonths", "Sex", "LifeStage", "Notes") VALUES (21, 'older', '老人', 780, 959, 'NotSpecified', '老年期', NULL);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (1, 'protein', '蛋白质', 'Protein', 'Macronutrient', '宏量营养素', 'g/d', '构成机体组织、酶和激素的重要成分，参与修复与免疫。', '蛋白质是构成肌肉、皮肤、毛发、酶、激素和抗体等重要物质的基础，也参与体内物质运输与酸碱平衡。膳食中的蛋白质主要来自鱼、禽、蛋、瘦肉、奶及奶制品、大豆及其制品。中国居民膳食指南（2022）建议平均每天摄入鱼、禽、蛋和瘦肉 120～200 克，奶及奶制品 300～500 克，大豆及坚果 25～35 克，并注意荤素搭配、种类多样。资料来源：百度百科“蛋白质”条目；中国居民膳食指南（2022）。', NULL, 1, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (2, 'carbohydrate', '碳水化合物', 'Carbohydrate', 'Macronutrient', '宏量营养素', 'g/d', '人体最主要的能量来源，优先选择全谷物和杂豆。', '碳水化合物是人体最经济、最主要的能量来源，参与构成细胞和组织，并有助于节约蛋白质。膳食指南（2022）建议每天摄入谷类 200～300 克，其中全谷物和杂豆 50～150 克，薯类 50～100 克，少吃精制糖和含糖饮料。资料来源：百度百科“碳水化合物”条目；中国居民膳食指南（2022）。', NULL, 2, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (3, 'fat', '脂肪', 'Fat', 'Macronutrient', '宏量营养素', 'g/d', '提供能量和必需脂肪酸，帮助脂溶性维生素吸收。', '脂肪是高能量营养素，提供必需脂肪酸，并促进维生素 A、D、E、K 等脂溶性维生素的吸收。膳食指南（2022）建议成年人每天烹调油 25～30 克，少吃油炸食品和动物脂肪，适当增加富含不饱和脂肪酸的植物油、鱼类和坚果。资料来源：百度百科“脂肪”条目；中国居民膳食指南（2022）。', NULL, 3, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (4, 'vitamin-a', '维生素 A', 'Vitamin A', 'Vitamin', '脂溶性维生素', 'μg RAE/d', '维持视觉、免疫和皮肤黏膜健康。', '维生素 A 参与视觉形成、免疫功能、生长发育和皮肤黏膜完整性。动物肝脏、蛋类、奶类富含视黄醇；深绿色和橙黄色蔬菜水果中的 β-胡萝卜素可在体内转化为维生素 A。膳食指南（2022）建议餐餐有蔬菜，保证每天摄入不少于 300 克新鲜蔬菜，其中深色蔬菜应占一半。资料来源：百度百科“维生素A”条目；中国居民膳食指南（2022）。', 1, 4, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (5, 'vitamin-b1', '维生素 B₁', 'Thiamin', 'Vitamin', '水溶性维生素', 'mg/d', '参与能量代谢，缺乏可影响神经系统。', '维生素 B₁（硫胺素）参与碳水化合物代谢和神经、心肌功能，长期严重缺乏可引起脚气病。全谷物、豆类、瘦肉、动物内脏是主要来源。谷物加工越精细，B 族维生素损失越多，因此膳食指南（2022）提倡增加全谷物摄入。资料来源：百度百科“维生素B1”条目；中国居民膳食指南（2022）。', 0, 5, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (6, 'vitamin-b12', '维生素 B₁₂', 'Cobalamin', 'Vitamin', '水溶性维生素', 'μg/d', '参与红细胞生成和神经系统功能，主要来自动物性食物。', '维生素 B₁₂（钴胺素）参与红细胞生成、DNA 合成和神经系统功能，缺乏可导致巨幼红细胞性贫血和神经损害。它几乎只存在于动物性食物中，如动物肝脏、肉类、蛋类、奶类和水产品，长期严格素食者需特别关注并咨询专业人员。资料来源：百度百科“维生素B12”条目；中国居民膳食指南（2022）。', 0, 6, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (7, 'vitamin-c', '维生素 C', 'Vitamin C', 'Vitamin', '水溶性维生素', 'mg/d', '抗氧化、参与胶原合成，并促进非血红素铁吸收。', '维生素 C（抗坏血酸）具有抗氧化作用，参与胶原蛋白合成、神经递质形成，并能促进非血红素铁的吸收。新鲜蔬菜和水果是主要来源，如鲜枣、猕猴桃、柑橘、草莓、西兰花、青椒等。维生素 C 怕热、怕光、易溶于水，长时间高温烹调会明显损失，建议急火快炒、适当生食。膳食指南（2022）建议天天吃水果，保证每天摄入 200～350 克新鲜水果。资料来源：百度百科“维生素C”条目；中国居民膳食指南（2022）。', 0, 7, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (8, 'vitamin-d', '维生素 D', 'Vitamin D', 'Vitamin', '脂溶性维生素', 'μg/d', '促进钙吸收和骨骼健康，日照是重要来源。', '维生素 D 主要通过调节钙、磷代谢维持骨骼健康，也参与免疫和肌肉功能。人体皮肤经紫外线照射可合成维生素 D，食物来源包括脂肪含量较高的鱼类、蛋黄、动物肝脏和强化食品。日照不足、户外活动少的人群更容易摄入不足，是否需要补充应结合个体情况咨询专业人员。资料来源：百度百科“维生素D”条目；中国居民膳食指南（2022）。', 1, 8, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (9, 'vitamin-e', '维生素 E', 'Vitamin E', 'Vitamin', '脂溶性维生素', 'mg/d', '抗氧化，保护细胞膜中的不饱和脂肪酸。', '维生素 E 是一类脂溶性抗氧化剂，主要作用是保护细胞膜和脂蛋白中的不饱和脂肪酸免受氧化损伤。植物油、坚果、种子和全谷物是主要来源。由于维生素 E 广泛存在于常见食物中，正常膳食通常不易缺乏，长期大剂量补充需谨慎。资料来源：百度百科“维生素E”条目；中国居民膳食指南（2022）。', 1, 9, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (10, 'vitamin-k', '维生素 K', 'Vitamin K', 'Vitamin', '脂溶性维生素', 'μg/d', '参与凝血和骨代谢，深绿色蔬菜是主要来源。', '维生素 K 参与凝血因子合成和骨代谢。深绿色蔬菜（如菠菜、西兰花、油菜）、纳豆和部分发酵食品是主要来源。正在服用华法林等抗凝药物的人群，应保持维生素 K 摄入相对稳定，并遵医嘱调整。资料来源：百度百科“维生素K”条目；中国居民膳食指南（2022）。', 1, 10, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (11, 'calcium', '钙', 'Calcium', 'Mineral', '常量元素', 'mg/d', '骨骼和牙齿的主要成分，参与神经与肌肉功能。', '钙是人体含量最多的矿物质，约 99% 存在于骨骼和牙齿中，其余参与神经传导、肌肉收缩和血液凝固。奶及奶制品是优质来源，豆制品、绿叶蔬菜、小鱼小虾也可提供。膳食指南（2022）建议每天摄入奶及奶制品 300～500 克，并经常食用豆制品。资料来源：百度百科“钙”条目；中国居民膳食指南（2022）。', NULL, 11, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (12, 'magnesium', '镁', 'Magnesium', 'Mineral', '常量元素', 'mg/d', '参与能量代谢和多种酶反应。', '镁参与体内 300 多种酶促反应，涉及能量代谢、神经肌肉兴奋性和骨骼构成。全谷物、坚果、豆类和深绿色蔬菜是主要来源。以精制谷物为主、蔬菜水果摄入不足的膳食结构，可能使镁摄入偏低。资料来源：百度百科“镁”条目；中国居民膳食指南（2022）。', NULL, 12, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (13, 'iron', '铁', 'Iron', 'Mineral', '微量元素', 'mg/d', '血红蛋白的重要组成，吸收受食物形态和搭配影响。', '铁是血红蛋白、肌红蛋白和多种酶的组成成分，参与氧的运输和能量代谢。动物性食物中的血红素铁吸收率较高，植物性食物中的非血红素铁易受植酸、多酚影响，而维生素 C 可促进其吸收。动物血、肝脏、红肉是良好来源。育龄期女性、孕妇和婴幼儿是缺铁的高风险人群。资料来源：百度百科“铁”条目；中国居民膳食指南（2022）。', NULL, 13, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (14, 'zinc', '锌', 'Zinc', 'Mineral', '微量元素', 'mg/d', '参与生长发育、免疫和味觉功能。', '锌参与生长发育、免疫功能、伤口愈合和味觉维持，也是多种酶的组成成分。贝壳类海产品、红肉、动物内脏、坚果是良好来源。植物性食物中的植酸会影响锌的吸收，以谷物豆类为主的人群应注意搭配。资料来源：百度百科“锌”条目；中国居民膳食指南（2022）。', NULL, 14, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (15, 'iodine', '碘', 'Iodine', 'Mineral', '微量元素', 'μg/d', '合成甲状腺激素，碘盐是主要来源。', '碘是合成甲状腺激素的必需元素，参与调节新陈代谢和生长发育。碘缺乏可导致甲状腺肿，孕期缺碘还会影响胎儿神经发育。海带、紫菜、海鱼等海产品含碘丰富，加碘食盐是我国居民碘的主要来源。膳食指南（2022）建议成年人每天食盐摄入不超过 5 克。资料来源：百度百科“碘”条目；中国居民膳食指南（2022）。', NULL, 15, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (16, 'selenium', '硒', 'Selenium', 'Mineral', '微量元素', 'μg/d', '抗氧化酶的重要组成，参与甲状腺激素代谢。', '硒是谷胱甘肽过氧化物酶等多种抗氧化酶的组成成分，参与甲状腺激素代谢和免疫调节。海产品、动物内脏、蛋类和坚果（尤其巴西坚果）是主要来源。硒的安全范围相对较窄，长期过量摄入可能产生不良反应，补充剂应在专业指导下使用。资料来源：百度百科“硒”条目；中国居民膳食指南（2022）。', NULL, 16, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (17, 'sodium', '钠', 'Sodium', 'Mineral', '常量元素', 'mg/d', '维持体液平衡和神经肌肉功能，主要来自食盐。', '钠是维持体液容量、渗透压和神经肌肉正常功能的重要元素，主要通过食盐（氯化钠）摄入。食盐中约 40% 是钠，1 克食盐约含 400 毫克钠。中国居民膳食指南（2022）建议成年人每天食盐摄入不超过 5 克，并减少酱油、腌制品等隐形盐的摄入。资料来源：百度百科“钠”条目；中国居民膳食指南（2022）。', NULL, 17, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (18, 'anthocyanin', '花青素', 'Anthocyanins', 'Other', '植物化合物', 'mg/d', '使蔬果呈紫红色的多酚类物质，具抗氧化作用。', '花青素是一类水溶性色素，广泛存在于紫甘蓝、蓝莓、葡萄、樱桃、紫薯、草莓等深色蔬果中。它属于植物化合物而非必需营养素，目前没有官方推荐摄入量。日常多吃深色蔬果是获取花青素的自然方式。资料来源：百度百科“花青素”条目；中国居民膳食指南（2022）。', 0, 18, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (19, 'lutein', '叶黄素', 'Lutein', 'Other', '类胡萝卜素', 'mg/d', '集中在视网膜黄斑区，帮助过滤蓝光。', '叶黄素是一种含氧类胡萝卜素，与玉米黄质一起集中在视网膜黄斑区，能吸收蓝光、减轻氧化损伤。深绿色蔬菜、玉米、蛋黄是主要来源，与油脂同烹更利于吸收。它不是必需营养素，暂无官方推荐量。资料来源：百度百科“叶黄素”条目；中国居民膳食指南（2022）。', 1, 19, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (20, 'lycopene', '番茄红素', 'Lycopene', 'Other', '类胡萝卜素', 'mg/d', '番茄等红色蔬果中的类胡萝卜素，抗氧化。', '番茄红素是一种红色类胡萝卜素，主要存在于番茄、西瓜、番石榴等红色蔬果中，具有抗氧化作用。它属脂溶性，加热和油脂可提高其溶出与吸收。属于植物化合物，暂无官方推荐摄入量。资料来源：百度百科“番茄红素”条目；中国居民膳食指南（2022）。', 1, 20, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (21, 'beta-carotene', 'β-胡萝卜素', 'Beta-Carotene', 'Other', '类胡萝卜素', 'μg/d', '维生素 A 的前体，深色蔬果中含量丰富。', 'β-胡萝卜素可在体内转化为维生素 A，被称为维生素 A 前体。胡萝卜、红薯、南瓜、深绿色蔬菜中含量丰富。它属脂溶性，用油烹调或与含脂食物同餐可提高吸收；优先从食物获取，不建议自行大剂量补充。资料来源：百度百科“β-胡萝卜素”条目；中国居民膳食指南（2022）。', 1, 21, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (22, 'dietary-fiber', '膳食纤维', 'Dietary Fiber', 'Macronutrient', '碳水化合物', 'g/d', '促进肠道蠕动、帮助控制血糖和血脂。', '膳食纤维是植物性食物中不能被人体消化吸收的碳水化合物。它有助于增加饱腹感、促进肠道蠕动、改善肠道菌群，并帮助控制血糖和血脂。全谷物、杂豆、薯类、蔬菜和水果是主要来源。资料来源：百度百科“膳食纤维”条目；中国居民膳食指南（2022）。', NULL, 22, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (23, 'potassium', '钾', 'Potassium', 'Mineral', '常量元素', 'mg/d', '维持体液平衡和正常血压，蔬果豆类含量高。', '钾是细胞内主要的阳离子，参与维持体液平衡、神经肌肉兴奋性和心脏节律，并有助于对抗钠升压作用。蔬菜、水果、豆类、薯类、菌菇含钾丰富。肾功能不全者需在医生指导下控制钾摄入。资料来源：百度百科“钾”条目；中国居民膳食指南（2022）。', NULL, 23, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (24, 'phosphorus', '磷', 'Phosphorus', 'Mineral', '常量元素', 'mg/d', '骨骼和牙齿的重要组成，参与能量代谢。', '磷是人体含量仅次于钙的矿物质，约 85% 存在于骨骼和牙齿中，其余参与能量代谢、核酸和细胞膜构成。磷广泛存在于各类食物中，正常膳食一般不易缺乏；加工食品中的磷酸盐添加剂是隐形磷的主要来源。资料来源：百度百科“磷”条目；中国居民膳食指南（2022）。', NULL, 24, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (25, 'copper', '铜', 'Copper', 'Mineral', '微量元素', 'mg/d', '参与铁代谢和抗氧化酶功能。', '铜是多种酶的组成成分，参与铁代谢、能量产生、结缔组织合成和抗氧化防御。动物肝脏、贝类、坚果、豆类、全谷物和可可含量较高。长期过量补充可能影响肝功能和锌吸收，补充剂应在专业指导下使用。资料来源：百度百科“铜”条目；中国居民膳食指南（2022）。', NULL, 25, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (26, 'vitamin-b2', '维生素 B₂', 'Riboflavin', 'Vitamin', '水溶性维生素', 'mg/d', '参与能量代谢，缺乏可引起口角炎。', '维生素 B₂（核黄素）参与碳水化合物、脂肪和蛋白质的代谢，维持皮肤、黏膜和视觉健康。奶类、蛋类、动物肝脏、瘦肉、绿叶蔬菜是主要来源。它怕光，牛奶等食物应避光保存。长期缺乏可引起口角炎、舌炎和脂溢性皮炎。资料来源：百度百科“维生素B2”条目；中国居民膳食指南（2022）。', 0, 26, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (27, 'vitamin-b6', '维生素 B₆', 'Pyridoxine', 'Vitamin', '水溶性维生素', 'mg/d', '参与氨基酸代谢和血红蛋白合成。', '维生素 B₆ 包括吡哆醇、吡哆醛和吡哆胺，参与氨基酸代谢、血红蛋白合成、神经递质生成和免疫功能。鸡肉、鱼肉、动物肝脏、土豆、香蕉、豆类和全谷物是主要来源。长期大剂量补充可能引起神经损伤。资料来源：百度百科“维生素B6”条目；中国居民膳食指南（2022）。', 0, 27, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (28, 'astaxanthin', '虾青素', 'Astaxanthin', 'Other', '类胡萝卜素', 'mg/d', '使三文鱼、虾蟹呈红色的类胡萝卜素，抗氧化。', '虾青素是一种红色类胡萝卜素，使三文鱼、虾、蟹等呈现橙红色，具有较强抗氧化作用。它属于植物/海洋生物化合物，不是必需营养素，目前没有官方推荐摄入量。三文鱼、虾蟹、藻类是其天然来源，属脂溶性，与油脂同餐更利于吸收。资料来源：百度百科“虾青素”条目；中国居民膳食指南（2022）。', 1, 28, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (29, 'vitamin-b3', '维生素 B₃', 'Niacin', 'Vitamin', '水溶性维生素', 'mg/d', '即烟酸，参与能量代谢，维持皮肤和神经系统健康。', '维生素 B₃（烟酸、尼克酸）参与体内能量代谢，维持皮肤、神经系统和消化系统健康。肉类、动物肝脏、鱼类、全谷物、豆类和坚果是主要来源。玉米中的烟酸多为结合型，需经碱处理才易被利用。长期大量补充可能引起皮肤潮红等不适。资料来源：百度百科“维生素B3”条目；中国居民膳食指南（2022）。', 0, 29, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (30, 'vitamin-b5', '维生素 B₅', 'Pantothenic Acid', 'Vitamin', '水溶性维生素', 'mg/d', '即泛酸，参与能量代谢和辅酶 A 的构成。', '维生素 B₅（泛酸）是辅酶 A 的组成成分，参与碳水化合物、脂肪和蛋白质的代谢。它广泛存在于各类食物中，动物肝脏、蛋类、肉类、豆类、全谷物和蘑菇含量较高，正常膳食一般不易缺乏。资料来源：百度百科“维生素B5”条目；中国居民膳食指南（2022）。', 0, 30, 1);
INSERT OR IGNORE INTO "Nutrients" ("Id", "Slug", "Name", "EnglishName", "Group", "Subgroup", "CanonicalUnit", "Summary", "Description", "IsFatSoluble", "DisplayOrder", "IsPublished") VALUES (31, 'sugar', '糖', 'Sugar', 'Macronutrient', '碳水化合物', 'g/d', '总糖，含天然糖与添加糖，过量增加龋齿和超重风险。', '糖包括食物中天然存在的糖（果糖、葡萄糖、乳糖等）和人工添加的游离糖。中国居民膳食指南（2022）建议添加糖每天不超过 50 克，最好控制在 25 克以下，同时少吃含糖饮料。水果和纯奶中的天然糖不计入添加糖，但总量过多仍会影响能量摄入。资料来源：百度百科“糖”条目；中国居民膳食指南（2022）。', NULL, 31, 1);
