INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (40, 'potato', '土豆（生）', '薯类', '生重计。发芽或表皮变绿的土豆不宜食用。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (41, 'potato-steamed', '土豆（蒸熟）', '薯类', '熟重计。蒸煮后维生素 C 有部分损失，矿物质相对稳定。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (42, 'sweet-potato', '红薯', '薯类', '生重计。可食部指去皮后的薯肉部分。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (43, 'yam', '山药', '薯类', '生重计。黏液蛋白接触皮肤可能引起瘙痒，处理时可戴手套。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (44, 'red-bean', '红豆', '豆类', '干重计。与煮熟后的豆沙、豆汤计量基准不同，不能直接比较。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (45, 'mung-bean', '绿豆', '豆类', '干重计。发芽后维生素 C 含量会明显升高。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (46, 'black-bean', '黑豆', '豆类', '干重计。蛋白质和钙含量在豆类中较高。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (47, 'south-tofu', '南豆腐', '豆制品', '制品计。含水量高，蛋白质和钙低于北豆腐。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (48, 'tofu-dry', '豆腐干', '豆制品', '制品计。脱水后蛋白质和钙浓度高于豆腐。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (49, 'soy-milk', '豆浆', '豆制品', '按体积计。与固体豆制品的计量基准不同，比较时需注意单位。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (50, 'yuba', '腐竹', '豆制品', '干重计。泡发后重量增加，不能与干重数值直接比较。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (51, 'soybean-oil', '大豆油', '油脂', '几乎全是脂肪，按每 100 克计。膳食指南建议每天烹调油 25～30 克。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (52, 'peanut-oil', '花生油', '油脂', '几乎全是脂肪，按每 100 克计。注意控制总用油量。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (53, 'olive-oil', '橄榄油', '油脂', '以单不饱和脂肪酸为主，按每 100 克计。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (54, 'salt', '食盐', '调味品', '以钠计：食盐约含 40% 钠，1 克食盐约含 400 毫克钠。膳食指南建议每天食盐不超过 5 克。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (56, 'pork-lean-cooked', '猪瘦肉（熟）', '畜禽肉', '熟重计。与生猪瘦肉为不同状态记录，数值因失水而浓缩，不能混算。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
