INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (61, 'chicken-breast-cooked', '鸡胸肉（熟）', '畜禽肉', '熟重计。水煮后失水，单位重量蛋白质浓度升高。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
