INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (68, 'peanut', '花生', '豆类', '能量较高，注意控制份量；霉变花生不可食用。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (69, 'sunflower-seed', '葵花籽仁', '坚果', '维生素 E 含量很高，但热量也高，每天一小把即可。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (70, 'almond', '杏仁', '坚果', '选择原味坚果，避免盐焗、糖衣带来的额外盐和糖。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
