INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (76, 'kelp', '海带（鲜）', '蔬菜 · 菌藻', '碘含量受产地、品种影响很大（干海带更高）；甲状腺疾病患者应遵医嘱。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
