INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (79, 'red-cabbage', '紫甘蓝', '蔬菜 · 叶菜', '紫红色来自花青素，凉拌或快炒可减少损失。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (80, 'kale', '羽衣甘蓝', '蔬菜 · 叶菜', '叶黄素和维生素 K 含量高，适合快炒或做沙拉。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
INSERT OR IGNORE INTO "Foods" ("Id", "Slug", "Name", "Category", "Description", "IsPublished", "SourceName", "SourceUrl") VALUES (81, 'pumpkin', '南瓜', '蔬菜 · 根茎', 'β-胡萝卜素丰富，与油脂同烹更利于吸收。', 1, '中国食物成分表（示例整理）', 'https://www.chinanutri.cn/');
