INSERT OR IGNORE INTO "AbsorptionEvidence" ("Id", "NutrientId", "Title", "Summary", "Direction", "Applicability", "EvidenceLevel", "SourceName", "SourceUrl", "ReviewedAtUtc") VALUES (1, 13, '血红素铁与非血红素铁的吸收途径不同', '肉类、内脏中的血红素铁吸收率通常高于植物性食物中的非血红素铁，且较少受同餐抑制因素影响。因此铁含量相同不等于可吸收的铁相同。', 'DependsOnContext', '一般膳食人群；具体比例随膳食结构、个体铁营养状况变化', '综述', 'NIH Office of Dietary Supplements · Iron Fact Sheet', 'https://ods.od.nih.gov/factsheets/Iron-HealthProfessional/', '2026-11-03 00:58:08.3918754');
INSERT OR IGNORE INTO "AbsorptionEvidence" ("Id", "NutrientId", "Title", "Summary", "Direction", "Applicability", "EvidenceLevel", "SourceName", "SourceUrl", "ReviewedAtUtc") VALUES (2, 13, '维生素 C 可促进非血红素铁吸收', '同餐摄入维生素 C 能在一定范围内提高非血红素铁的吸收，是植物性膳食中较明确的促进因素。研究条件下可见约 2～3 倍的相对提高，但具体幅度取决于剂量与膳食背景。', 'Enhances', '以植物性食物为主的一餐，且同餐含维生素 C', '临床研究综述', 'NIH Office of Dietary Supplements · Iron Fact Sheet', 'https://ods.od.nih.gov/factsheets/Iron-HealthProfessional/', '2026-11-03 00:58:08.3918754');
INSERT OR IGNORE INTO "AbsorptionEvidence" ("Id", "NutrientId", "Title", "Summary", "Direction", "Applicability", "EvidenceLevel", "SourceName", "SourceUrl", "ReviewedAtUtc") VALUES (3, 13, '植酸与多酚会降低铁吸收', '全谷物、豆类中的植酸，以及茶、咖啡中的多酚，会与铁结合而降低非血红素铁的吸收。', 'Inhibits', '与富含植酸或多酚的食物同餐时', '综述', 'NIH Office of Dietary Supplements · Iron Fact Sheet', 'https://ods.od.nih.gov/factsheets/Iron-HealthProfessional/', '2026-11-03 00:58:08.3918754');
INSERT OR IGNORE INTO "AbsorptionEvidence" ("Id", "NutrientId", "Title", "Summary", "Direction", "Applicability", "EvidenceLevel", "SourceName", "SourceUrl", "ReviewedAtUtc") VALUES (4, 13, '钙与铁同餐可能相互影响', '较大剂量的钙补充剂与铁同服时可能降低铁吸收，但常规膳食中的钙影响通常较小。是否成立取决于剂量与形式。', 'DependsOnContext', '补充剂同服场景；普通膳食证据不一致', '综述', 'NIH Office of Dietary Supplements · Iron Fact Sheet', 'https://ods.od.nih.gov/factsheets/Iron-HealthProfessional/', '2026-11-03 00:58:08.3918754');
INSERT OR IGNORE INTO "AbsorptionEvidence" ("Id", "NutrientId", "Title", "Summary", "Direction", "Applicability", "EvidenceLevel", "SourceName", "SourceUrl", "ReviewedAtUtc") VALUES (5, 11, '维生素 D 参与钙的吸收与利用', '维生素 D 通过调节钙磷代谢影响钙的吸收。膳食钙的利用还受年龄、生理阶段与总摄入量影响。', 'Enhances', '维生素 D 状态不足的人群需特别关注', '综述', 'NIH Office of Dietary Supplements · Calcium Fact Sheet', 'https://ods.od.nih.gov/factsheets/Calcium-HealthProfessional/', '2026-11-03 00:58:08.3918754');
INSERT OR IGNORE INTO "AbsorptionEvidence" ("Id", "NutrientId", "Title", "Summary", "Direction", "Applicability", "EvidenceLevel", "SourceName", "SourceUrl", "ReviewedAtUtc") VALUES (6, 11, '单次摄入量与吸收比例并非线性', '随着单次钙摄入量增加，吸收比例通常下降。因此把一天的量分散到多餐，往往比一次大量摄入更有利。', 'DependsOnContext', '评估单餐或补充剂剂量时', '综述', 'NIH Office of Dietary Supplements · Calcium Fact Sheet', 'https://ods.od.nih.gov/factsheets/Calcium-HealthProfessional/', '2026-11-03 00:58:08.3918754');
INSERT OR IGNORE INTO "AbsorptionEvidence" ("Id", "NutrientId", "Title", "Summary", "Direction", "Applicability", "EvidenceLevel", "SourceName", "SourceUrl", "ReviewedAtUtc") VALUES (7, 14, '植酸会降低锌的吸收', '全谷物和豆类中的植酸可与锌结合，降低其吸收。发酵、浸泡等处理可减少部分植酸。', 'Inhibits', '以未精制谷物、豆类为主食时', '综述', 'NIH Office of Dietary Supplements · Zinc Fact Sheet', 'https://ods.od.nih.gov/factsheets/Zinc-HealthProfessional/', '2026-11-03 00:58:08.3918754');
INSERT OR IGNORE INTO "AbsorptionEvidence" ("Id", "NutrientId", "Title", "Summary", "Direction", "Applicability", "EvidenceLevel", "SourceName", "SourceUrl", "ReviewedAtUtc") VALUES (8, 7, '维生素 C 的吸收存在剂量与个体差异', '在常规摄入范围内吸收比例较高，随单次剂量增大而下降。吸烟、感染等状态可能提高需要量。', 'DependsOnContext', '评估补充剂剂量与吸烟人群时', '综述', 'NIH Office of Dietary Supplements · Vitamin C Fact Sheet', 'https://ods.od.nih.gov/factsheets/VitaminC-HealthProfessional/', '2026-11-03 00:58:08.3918754');
INSERT OR IGNORE INTO "AbsorptionEvidence" ("Id", "NutrientId", "Title", "Summary", "Direction", "Applicability", "EvidenceLevel", "SourceName", "SourceUrl", "ReviewedAtUtc") VALUES (9, 4, '维生素 A 的吸收与脂肪和形式有关', '视黄醇类与类胡萝卜素类的吸收和转化效率不同；膳食脂肪有助于脂溶性维生素的吸收。', 'DependsOnContext', '低脂膳食或主要依赖植物性来源时', '综述', 'NIH Office of Dietary Supplements · Vitamin A Fact Sheet', 'https://ods.od.nih.gov/factsheets/VitaminA-HealthProfessional/', '2026-11-03 00:58:08.3918754');
INSERT OR IGNORE INTO "AbsorptionEvidence" ("Id", "NutrientId", "Title", "Summary", "Direction", "Applicability", "EvidenceLevel", "SourceName", "SourceUrl", "ReviewedAtUtc") VALUES (10, 8, '维生素 D 的来源不止膳食', '除食物外，皮肤经日照合成维生素 D 是重要来源。膳食参考值通常是在假设日照有限的前提下制定。', 'DependsOnContext', '日照不足、户外活动少的人群', '综述', 'NIH Office of Dietary Supplements · Vitamin D Fact Sheet', 'https://ods.od.nih.gov/factsheets/VitaminD-HealthProfessional/', '2026-11-03 00:58:08.3918754');
INSERT OR IGNORE INTO "AbsorptionEvidence" ("Id", "NutrientId", "Title", "Summary", "Direction", "Applicability", "EvidenceLevel", "SourceName", "SourceUrl", "ReviewedAtUtc") VALUES (11, 6, '吸收依赖胃内因子，来源以动物性食物为主', '维生素 B12 需要与胃分泌的内因子结合才能被吸收；胃切除、萎缩性胃炎或长期服用抑酸药的人群，吸收可能下降。它几乎只存在于动物性食物中。', 'DependsOnContext', '老年人、胃部手术或长期抑酸治疗人群', '综述', 'NIH Office of Dietary Supplements · Vitamin B12 Fact Sheet', 'https://ods.od.nih.gov/factsheets/VitaminB12-HealthProfessional/', '2026-11-03 00:58:08.3918754');
INSERT OR IGNORE INTO "AbsorptionEvidence" ("Id", "NutrientId", "Title", "Summary", "Direction", "Applicability", "EvidenceLevel", "SourceName", "SourceUrl", "ReviewedAtUtc") VALUES (12, 9, '脂溶性，随膳食脂肪一起吸收', '维生素 E 属脂溶性维生素，膳食脂肪有助于其吸收；植物油、坚果、种子和全谷物是主要来源。', 'DependsOnContext', '低脂膳食或脂肪吸收不良人群', '综述', 'NIH Office of Dietary Supplements · Vitamin E Fact Sheet', 'https://ods.od.nih.gov/factsheets/VitaminE-HealthProfessional/', '2026-11-03 00:58:08.3918754');
INSERT OR IGNORE INTO "AbsorptionEvidence" ("Id", "NutrientId", "Title", "Summary", "Direction", "Applicability", "EvidenceLevel", "SourceName", "SourceUrl", "ReviewedAtUtc") VALUES (13, 10, '与抗凝药物需要保持稳定', '维生素 K 参与凝血。正在服用华法林等抗凝药的人，应保持维生素 K 摄入相对稳定，避免短期内大幅波动。', 'DependsOnContext', '服用华法林等抗凝药物的人群', '综述', 'NIH Office of Dietary Supplements · Vitamin K Fact Sheet', 'https://ods.od.nih.gov/factsheets/VitaminK-HealthProfessional/', '2026-11-03 00:58:08.3918754');
INSERT OR IGNORE INTO "AbsorptionEvidence" ("Id", "NutrientId", "Title", "Summary", "Direction", "Applicability", "EvidenceLevel", "SourceName", "SourceUrl", "ReviewedAtUtc") VALUES (14, 15, '碘盐是主要来源，孕期需求增加', '碘是合成甲状腺激素的原料，加碘食盐是我国居民碘的主要来源；海带、紫菜、海鱼等海产品也富含碘。孕期和哺乳期需求增加。', 'DependsOnContext', '碘缺乏地区、孕期与哺乳期女性', '综述', 'NIH Office of Dietary Supplements · Iodine Fact Sheet', 'https://ods.od.nih.gov/factsheets/Iodine-HealthProfessional/', '2026-11-03 00:58:08.3918754');
INSERT OR IGNORE INTO "AbsorptionEvidence" ("Id", "NutrientId", "Title", "Summary", "Direction", "Applicability", "EvidenceLevel", "SourceName", "SourceUrl", "ReviewedAtUtc") VALUES (15, 12, '植酸与补充剂剂量影响吸收', '全谷物、豆类中的植酸可能降低镁的吸收；大剂量补充剂可能引起腹泻，分次随餐服用更利于耐受。', 'DependsOnContext', '以精制谷物为主或使用补充剂时', '综述', 'NIH Office of Dietary Supplements · Magnesium Fact Sheet', 'https://ods.od.nih.gov/factsheets/Magnesium-HealthProfessional/', '2026-11-03 00:58:08.3918754');

