-- 干重计的数值对"直接吃多少"没有参考意义，从食物库中移除；幂等，可重复执行
-- ---------------------------------------------------------------------------
DELETE FROM "FoodNutrients" WHERE "FoodId" IN (
  SELECT "Id" FROM "Foods" WHERE "Slug" IN ('wood-ear', 'nori', 'shiitake-dried', 'dried-shrimp', 'yuba'));
DELETE FROM "Foods" WHERE "Slug" IN ('wood-ear', 'nori', 'shiitake-dried', 'dried-shrimp', 'yuba');

